SELECT CASE WHEN date_diff('day',OrderDate,DATE '2016-05-31')=0 THEN '0 days' WHEN date_diff('day',OrderDate,DATE '2016-05-31')<=7 THEN '1-7 days' WHEN date_diff('day',OrderDate,DATE '2016-05-31')<=30 THEN '8-30 days' WHEN date_diff('day',OrderDate,DATE '2016-05-31')<=90 THEN '31-90 days' ELSE '91+ days' END AgeBucket,COUNT(DISTINCT OrderID) Orders,COUNT(*) Lines,SUM(UnpickedUnits)::BIGINT Units FROM analytics.order_lines WHERE ScenarioID='base' AND UnpickedUnits>0 GROUP BY 1 ORDER BY MIN(OrderDate) DESC